// Renders the campaign instructions from templates/instructions.md and
// campaign.yaml, writes the generated files, and checks their fingerprints
// for hand edits. Errors are returned as data, never thrown.
//
// Template language:
//   {{a.b.c}}              value at that path in campaign.yaml (missing: empty)
//   {{#if a.b}}...{{/if}}  kept when the value is truthy (no else, no nesting)
//   {{#each list}}...{{/each}}  repeated per item; inside it only {{id}},
//                          {{folder}} and {{type}} are available
// A block tag alone on its line removes that whole line (no blank output).
// Any other {{...}} is an error ("bad-template") at its line.

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { parseYamlLite } from './yaml-lite.mjs';

const DEFAULT_TEMPLATE = path.resolve(import.meta.dirname, '../../templates/instructions.md');
const PLUGIN_JSON = path.resolve(import.meta.dirname, '../../.claude-plugin/plugin.json');
// The plugin folder: the parent of the scripts folder. The generated instructions
// state this path for the case where CLAUDE_PLUGIN_ROOT is empty.
export const PLUGIN_DIR = path.resolve(import.meta.dirname, '../..');

const CONFIG_PATH = 'campaign.yaml';
const AGENT_PATH = '.campaign/instructions/agent.md';
const CUSTOMIZATIONS_PATH = '.campaign/customizations.md';
const VERSION_PATH = '.campaign/version.yaml';
const CLAUDE_PATH = 'CLAUDE.md';
const SETTINGS_PATH = '.claude/settings.json';
// Project permissions: the skills of this framework and their own state folder.
// The Bash rules come from the allowed-tools of every skill (see projectSettingsText).
// The master's rules go in .claude/settings.local.json, which is never generated.
const SKILLS_DIR = path.join(PLUGIN_DIR, 'skills');
const FIXED_RULES = [
  'Skill(yllir:*)',
  'Edit(.campaign/state/**)',
  'Edit(.campaign/drafts/**)',
  'Edit(.campaign/image-providers/**)',
  'Edit(.campaign/styles/**)',
];
const PLUGIN_UPDATE_COMMAND = 'claude plugin update *';
const ALLOWED_TOOLS_LINE = /^allowed-tools:[ \t]*(.*)$/m;
const BASH_ENTRY_RE = /Bash\(([^()]*)\)/g;
const PLUGIN_NODE_SCRIPT_RE = /^node "\$\{CLAUDE_PLUGIN_ROOT\}\/(.+)" \*$/;

const NOTICE =
  '<!-- Generated by Yllir. Do not edit: changes are lost. Your own rules go in .campaign/customizations.md -->';
const CLAUDE_TEXT = `${NOTICE}\n@${AGENT_PATH}\n@${CUSTOMIZATIONS_PATH}\n`;

const PATH_RE = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$/;
const TAG_RE = /\{\{([^{}]*)\}\}/g;
const STANDALONE_TAG_RE = /^[ \t]*\{\{[^{}]*\}\}[ \t]*$/;
const ITEM_KEYS = ['id', 'folder', 'type'];

// ---------------------------------------------------------------- template

/**
 * Renders a template against a parsed campaign.yaml object.
 * @returns {{ text: string, errors: Array<{line: number, code: string, message: string}> }}
 */
export function renderTemplate(templateText, config) {
  const errors = [];
  const tokens = tokenize(templateText, errors);
  const nodes = buildTree(tokens, errors);
  const parts = [];
  renderNodes(nodes, config, null, errors, parts);
  return { text: parts.join(''), errors };
}

function templateError(errors, line, message) {
  errors.push({ line, code: 'bad-template', message });
}

// Splits the template into text chunks and tags. A block tag that is the only
// content of its line also consumes the line break.
function tokenize(text, errors) {
  const tokens = [];
  const lines = text.split('\n');
  lines.forEach((line, index) => {
    const no = index + 1;
    const eol = index < lines.length - 1 ? '\n' : '';

    if (STANDALONE_TAG_RE.test(line)) {
      const inner = line.trim().slice(2, -2).trim();
      if (inner.startsWith('#') || inner.startsWith('/')) {
        pushTag(tokens, inner, no, errors);
        return;
      }
    }

    let pos = 0;
    for (const match of line.matchAll(TAG_RE)) {
      pushText(tokens, line.slice(pos, match.index), no, errors);
      pushTag(tokens, match[1].trim(), no, errors);
      pos = match.index + match[0].length;
    }
    pushText(tokens, line.slice(pos) + eol, no, errors);
  });
  return tokens;
}

function pushText(tokens, value, line, errors) {
  if (value.includes('{{') || value.includes('}}')) {
    templateError(errors, line, 'unclosed or malformed tag');
    return;
  }
  if (value !== '') {
    tokens.push({ kind: 'text', value });
  }
}

function pushTag(tokens, inner, line, errors) {
  const open = /^#(if|each)\s+(\S+)$/.exec(inner);
  if (open !== null) {
    if (!PATH_RE.test(open[2])) {
      templateError(errors, line, `invalid path in {{${inner}}}`);
      return;
    }
    tokens.push({ kind: 'open', type: open[1], path: open[2], line });
    return;
  }
  const close = /^\/(if|each)$/.exec(inner);
  if (close !== null) {
    tokens.push({ kind: 'close', type: close[1], line });
    return;
  }
  if (PATH_RE.test(inner)) {
    tokens.push({ kind: 'var', path: inner, line });
    return;
  }
  templateError(errors, line, `unknown tag {{${inner}}}`);
}

// Groups tokens into nodes. Blocks may not nest.
function buildTree(tokens, errors) {
  const root = [];
  let block = null;
  for (const token of tokens) {
    if (token.kind === 'open') {
      if (block !== null) {
        templateError(errors, token.line, 'nested blocks are not supported');
        continue;
      }
      block = { kind: token.type, path: token.path, line: token.line, body: [] };
      root.push(block);
    } else if (token.kind === 'close') {
      if (block === null || block.kind !== token.type) {
        templateError(errors, token.line, `{{/${token.type}}} without a matching open tag`);
        continue;
      }
      block = null;
    } else if (block !== null) {
      block.body.push(token);
    } else {
      root.push(token);
    }
  }
  if (block !== null) {
    templateError(errors, block.line, `{{#${block.kind} ${block.path}}} is never closed`);
  }
  return root;
}

function renderNodes(nodes, config, item, errors, out) {
  for (const node of nodes) {
    if (node.kind === 'text') {
      out.push(node.value);
    } else if (node.kind === 'var') {
      renderVar(node, config, item, errors, out);
    } else if (node.kind === 'if') {
      if (isTruthy(getPath(config, node.path))) {
        renderNodes(node.body, config, null, errors, out);
      }
    } else if (node.kind === 'each') {
      renderEach(node, config, errors, out);
    }
  }
}

function renderVar(node, config, item, errors, out) {
  let value;
  if (item !== null) {
    if (!ITEM_KEYS.includes(node.path)) {
      templateError(
        errors,
        node.line,
        `inside #each only {{id}}, {{folder}} and {{type}} are available, not {{${node.path}}}`,
      );
      return;
    }
    value = item[node.path];
  } else {
    value = getPath(config, node.path);
  }
  if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
    templateError(errors, node.line, `{{${node.path}}} is a mapping, not a value`);
    return;
  }
  if (Array.isArray(value)) {
    out.push(value.map((entry) => (entry === null || entry === undefined ? '' : String(entry))).join(', '));
    return;
  }
  out.push(value === undefined || value === null ? '' : String(value));
}

function renderEach(node, config, errors, out) {
  const list = getPath(config, node.path);
  if (list === undefined || list === null) {
    return;
  }
  if (!Array.isArray(list)) {
    templateError(errors, node.line, `{{#each ${node.path}}} expects a list`);
    return;
  }
  for (const item of list) {
    if (item === null || typeof item !== 'object' || Array.isArray(item)) {
      templateError(errors, node.line, `items of {{#each ${node.path}}} must be mappings`);
      continue;
    }
    renderNodes(node.body, config, item, errors, out);
  }
}

function getPath(object, dottedPath) {
  let current = object;
  for (const key of dottedPath.split('.')) {
    if (current === null || typeof current !== 'object') {
      return undefined;
    }
    current = current[key];
  }
  return current;
}

function isTruthy(value) {
  if (value === undefined || value === null || value === false || value === '') {
    return false;
  }
  if (Array.isArray(value)) {
    return value.length > 0;
  }
  return true;
}

// ---------------------------------------------------------------- generation

/**
 * Generates the instruction files of a campaign.
 * @returns {{ written: string[], fingerprints: Array<{path: string, sha256: string}>, errors: object[] }}
 */
export function generateInstructions(campaignRoot, { templatePath = DEFAULT_TEMPLATE } = {}) {
  const root = path.resolve(campaignRoot);
  const fail = (errors) => ({ written: [], fingerprints: [], errors });

  const configText = readTextOrNull(path.join(root, CONFIG_PATH));
  if (configText === null) {
    return fail([{ file: CONFIG_PATH, line: null, code: 'missing-config', message: 'campaign.yaml not found' }]);
  }
  const parsed = parseYamlLite(configText);
  if (parsed.errors.length > 0) {
    return fail(
      parsed.errors.map((error) => ({
        file: CONFIG_PATH,
        line: error.line,
        code: 'yaml-syntax',
        message: error.message,
      })),
    );
  }
  if (parsed.data === null || typeof parsed.data !== 'object' || Array.isArray(parsed.data)) {
    return fail([{ file: CONFIG_PATH, line: null, code: 'invalid-config', message: 'campaign.yaml must be a mapping' }]);
  }

  const templateText = readTextOrNull(templatePath);
  if (templateText === null) {
    return fail([{ file: templatePath, line: null, code: 'missing-template', message: 'template not found' }]);
  }
  // The generator's own values are added under `plugin`, after campaign.yaml.
  const rendered = renderTemplate(templateText, { ...parsed.data, plugin: { root: PLUGIN_DIR } });
  if (rendered.errors.length > 0) {
    return fail(rendered.errors.map((error) => ({ file: templatePath, ...error })));
  }

  const pluginText = readTextOrNull(PLUGIN_JSON);
  let frameworkVersion = null;
  try {
    frameworkVersion = JSON.parse(pluginText).version;
  } catch {
    frameworkVersion = null;
  }
  if (typeof frameworkVersion !== 'string') {
    return fail([{ file: PLUGIN_JSON, line: null, code: 'invalid-plugin', message: 'plugin.json has no version' }]);
  }

  const written = [];
  const generated = [];
  const writeFile = (relPath, text) => {
    const absPath = path.join(root, relPath);
    fs.mkdirSync(path.dirname(absPath), { recursive: true });
    fs.writeFileSync(absPath, text, 'utf8');
    written.push(relPath);
  };
  const fingerprint = (relPath, text) => {
    generated.push({ path: relPath, sha256: sha256(text) });
  };

  writeFile(AGENT_PATH, rendered.text);
  fingerprint(AGENT_PATH, rendered.text);
  writeFile(CLAUDE_PATH, CLAUDE_TEXT);
  fingerprint(CLAUDE_PATH, CLAUDE_TEXT);
  const settingsText = projectSettingsText();
  writeFile(SETTINGS_PATH, settingsText);
  fingerprint(SETTINGS_PATH, settingsText);

  if (readTextOrNull(path.join(root, CUSTOMIZATIONS_PATH)) === null) {
    writeFile(CUSTOMIZATIONS_PATH, `${customizationsHeader(parsed.data)}\n`);
  }

  generated.sort((a, b) => compareStrings(a.path, b.path));
  const versionText = [
    `framework_version: "${frameworkVersion}"`,
    'schema: 1',
    'generated:',
    ...generated.flatMap((entry) => [`  - path: "${entry.path}"`, `    sha256: "${entry.sha256}"`]),
  ].join('\n') + '\n';
  writeFile(VERSION_PATH, versionText);

  return { written, fingerprints: generated, errors: [] };
}

function customizationsHeader(config) {
  const language = config.language !== null && typeof config.language === 'object' ? config.language.main : undefined;
  return language === 'it' ? '# Le tue regole' : '# Your rules';
}

// ---------------------------------------------------------------- project settings

/** Every SKILL.md under the skills folder, sorted. */
export function skillFiles(skillsDir = SKILLS_DIR) {
  const files = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.name === 'SKILL.md') files.push(full);
    }
  };
  walk(skillsDir);
  return files.sort(compareStrings);
}

/** The value of the allowed-tools line of a SKILL.md text, or null. Read as one line: the frontmatter helper does not take hyphenated keys. */
export function allowedToolsOf(skillText) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---/.exec(skillText);
  if (match === null) return null;
  const line = ALLOWED_TOOLS_LINE.exec(match[1]);
  return line === null ? null : line[1].trim();
}

/**
 * The Bash allow rules and the fixed rules of a campaign's project settings, sorted and unique.
 * Each plugin script entry of a skill, written with the CLAUDE_PLUGIN_ROOT variable, becomes a rule
 * whose folder is a wildcard, so that it matches the plugin wherever it is installed. The unrooted
 * entries of the skills name the same scripts and add no rule.
 */
export function projectAllowRules(skillsDir = SKILLS_DIR) {
  const rules = new Set(FIXED_RULES);
  for (const file of skillFiles(skillsDir)) {
    const allowed = allowedToolsOf(fs.readFileSync(file, 'utf8'));
    if (allowed === null) continue;
    for (const match of allowed.matchAll(BASH_ENTRY_RE)) {
      const command = match[1];
      const script = PLUGIN_NODE_SCRIPT_RE.exec(command);
      if (script !== null) rules.add(`Bash(node "*/${script[1]}" *)`);
      else if (command === PLUGIN_UPDATE_COMMAND) rules.add(`Bash(${PLUGIN_UPDATE_COMMAND})`);
    }
  }
  return [...rules].sort(compareStrings);
}

/** Text of .claude/settings.json: the permissions every campaign gets, generated from the skills. */
export function projectSettingsText(skillsDir = SKILLS_DIR) {
  return `${JSON.stringify({ permissions: { allow: projectAllowRules(skillsDir) } }, null, 2)}\n`;
}

// ---------------------------------------------------------------- fingerprints

/**
 * Compares the generated files with the fingerprints in version.yaml.
 * A missing or unreadable version.yaml counts as missing_version_file.
 * @returns {{ ok: boolean, changed: string[], missing_version_file: boolean }}
 */
export function checkFingerprints(campaignRoot) {
  const root = path.resolve(campaignRoot);
  const versionText = readTextOrNull(path.join(root, VERSION_PATH));
  const parsed = versionText === null ? null : parseYamlLite(versionText);
  const generated = parsed !== null && parsed.errors.length === 0 && parsed.data !== null ? parsed.data.generated : undefined;
  const wellFormed =
    Array.isArray(generated) &&
    generated.every((entry) => entry !== null && typeof entry === 'object' && typeof entry.path === 'string' && typeof entry.sha256 === 'string');
  if (!wellFormed) {
    return { ok: false, changed: [], missing_version_file: true };
  }

  const changed = [];
  for (const entry of generated) {
    const content = readBufferOrNull(path.join(root, entry.path));
    if (content === null || sha256(content) !== entry.sha256) {
      changed.push(entry.path);
    }
  }
  return { ok: changed.length === 0, changed, missing_version_file: false };
}

// ---------------------------------------------------------------- helpers

function sha256(content) {
  return crypto.createHash('sha256').update(content).digest('hex');
}

function compareStrings(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

function readBufferOrNull(file) {
  try {
    return fs.readFileSync(file);
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') return null;
    throw err;
  }
}

function readTextOrNull(file) {
  const buffer = readBufferOrNull(file);
  return buffer === null ? null : buffer.toString('utf8');
}
